-- Minimal stand-in for the hotel PMS (SMILE_FO) so the agent can be exercised on a Mac with no real PMS.
-- Only the base tables the agent's pms-procedures.sql ALTERs/reads for the E2E are created here; the
-- srCI_* procedures and SMILE_PICTURE tables come from the real bundle (installed by the agent itself).
-- Applied by tests/.../AgentSqlServerE2ETests (batches separated by a line holding only GO).
IF DB_ID('SMILE_FO') IS NOT NULL ALTER DATABASE SMILE_FO SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
GO
IF DB_ID('SMILE_FO') IS NOT NULL DROP DATABASE SMILE_FO;
GO
IF DB_ID('SMILE_PICTURE') IS NOT NULL DROP DATABASE SMILE_PICTURE;
GO
CREATE DATABASE SMILE_FO;
GO
CREATE DATABASE SMILE_PICTURE;
GO
USE SMILE_FO;
GO
-- The real SMILE schema is not in this repo. Each table below carries a PERMISSIVE SUPERSET of the columns the
-- bundled procedures reference (nullable, types guessed from names), so the procedures compile. It proves the
-- agent's install/execute/delta mechanics; it says nothing about the procedures' business correctness.
