    DepartureDate DATETIME NULL,
    DepartureTime DATETIME NULL,
    Description NVARCHAR(200) NULL,
    DisabledFlag DECIMAL(18,0) NULL,
    ExternalConfirmNumber NVARCHAR(200) NULL,
    FirstName NVARCHAR(200) NULL,
    FolioBalanceCode NVARCHAR(200) NULL,
    FolioCurrencyCode NVARCHAR(200) NULL,
    FolioExRate DECIMAL(18,4) NULL,
    FolioStatus DECIMAL(18,0) NULL,
    FolioSubNum DECIMAL(18,0) NULL,
    GroupCode NVARCHAR(200) NULL,
    HotelDate DATETIME NULL,
    IncludeBF NVARCHAR(200) NULL,
    LastChangeClerkID NVARCHAR(200) NULL,
    LastChangeTime DATETIME NULL,
    LastName NVARCHAR(200) NULL,
    MailM NVARCHAR(200) NULL,
    MarketSegmentCode NVARCHAR(200) NULL,
    MemberID NVARCHAR(200) NULL,
    NetRate DECIMAL(18,4) NULL,
    NoShowFlag DECIMAL(18,0) NULL,
    Notice NVARCHAR(200) NULL,
    NumAdult DECIMAL(18,0) NULL,
    NumChild DECIMAL(18,0) NULL,
    NumEnf DECIMAL(18,0) NULL,
    NumRoom DECIMAL(18,0) NULL,
    PaymentCode NVARCHAR(200) NULL,
    Position NVARCHAR(200) NULL,
    ProfileNumber NVARCHAR(200) NULL,
    RateAmount DECIMAL(18,4) NULL,
    RateOverideFlag DECIMAL(18,0) NULL,
    ReportDate DATETIME NULL,
    ReservationClerkID NVARCHAR(200) NULL,
    ReservationTime DATETIME NULL,
    RoomCode NVARCHAR(200) NULL,
    RoomTypeBooked NVARCHAR(200) NULL,
    RoomTypeCode NVARCHAR(200) NULL,
    SecurityCode NVARCHAR(200) NULL,
    SecurityLevel DECIMAL(18,0) NULL,
