-- Guest tables: the columns the guest-write procedures (srCI_UpsertAdditionalName, srCI_UpsertGuestProfile,
-- srCI_UpdGuestInfor) touch. Name/address are varchar as in SMILE_FO (TCVN-3), so the E2E can check what lands.
CREATE TABLE dbo.AdditionalName (
    IdAddition DECIMAL(18,0) IDENTITY(1,1) PRIMARY KEY, FolioNum DECIMAL(18,0), FolioSubNum DECIMAL(18,0), ConfirmNum DECIMAL(18,0),
    LastName VARCHAR(50), FirstName VARCHAR(50), Title VARCHAR(10), Gender BIT, BirthDate DATETIME, PassportNum VARCHAR(20),
    NationalityCode VARCHAR(3), MobileNum VARCHAR(20), TeleNum VARCHAR(20), Email VARCHAR(50), Occupation VARCHAR(50),
    Address1 VARCHAR(200), IsChild BIT, VisaNum VARCHAR(20), Province VARCHAR(200), VisaDateA DATETIME, AdtStatus INT,
    CompanyName VARCHAR(200), Address2 VARCHAR(200), Address3 VARCHAR(200), Address4 VARCHAR(200), PostalCode VARCHAR(10),
    Country VARCHAR(20), FaxNum VARCHAR(20), LanguageCode VARCHAR(2), WebSite VARCHAR(35), ArrivalTime DATETIME,
    DepartureTime DATETIME, AOriginCode VARCHAR(10), ACancelNum DECIMAL(18,0), AProfileNum DECIMAL(18,0), ConfirmPrintFlag BIT,
    VIPLevel INT, SmokerFlag BIT, NewspaperCode VARCHAR(2), SequenceNum INT, Geographic1Code VARCHAR(3), Geographic2Code VARCHAR(3),
    ResidenceCard VARCHAR(30), Purpose VARCHAR(50), EntryDateFrom DATETIME, EntryDateTo DATETIME, EntryFrom VARCHAR(20),
    EntryPort VARCHAR(20), IsSuedBy VARCHAR(40), Remark VARCHAR(1000), IsVNResident INT, IsTransfer INT, DocType VARCHAR(30),
    DocIssueDate DATETIME, VisaFree INT, PassportType VARCHAR(30), Religion VARCHAR(30), TakeCareC VARCHAR(100), TakeCareP VARCHAR(100),
    -- read by other bundled procedures (permissive superset, as above)
    TravelAgent1Code VARCHAR(20), VIPLevelCode VARCHAR(10), LastChangeTime DATETIME, LastChangeClerkID VARCHAR(20),
    NumVisit INT, NumNight INT, TotalRevenue DECIMAL(18,4), TotalRoomRevenue DECIMAL(18,4), FirstVisitDate DATETIME);
CREATE TABLE dbo.Profile (
    ProfileNumber DECIMAL(18,0) PRIMARY KEY, LastName VARCHAR(50), FirstName VARCHAR(50), Title VARCHAR(10), NationalCode VARCHAR(20),
    PassportNum VARCHAR(20), BirthDate DATETIME, Email VARCHAR(50), PhoneNum VARCHAR(20), Gender BIT, Occupation VARCHAR(50), Address1 VARCHAR(200),
    CompanyName VARCHAR(200), TravelAgent1Code VARCHAR(20), VIPLevelCode VARCHAR(10), LastChangeTime DATETIME, LastChangeClerkID VARCHAR(20),
    NumVisit INT, NumNight INT, TotalRevenue DECIMAL(18,4), TotalRoomRevenue DECIMAL(18,4), FirstVisitDate DATETIME);
CREATE TABLE dbo.AutoProfileNumber (ProfileNumber DECIMAL(18,0));
INSERT dbo.AutoProfileNumber VALUES (100);
GO
-- Folio columns that only surface once the guest tables above exist (procedures joining them are no longer deferred).
ALTER TABLE dbo.Folio ADD CompanyName NVARCHAR(200) NULL, TravelAgent1Code INT NULL;
-- RT-1496: what srCI_PostFolioPayment and the bill's TransactionGroup read.
ALTER TABLE dbo.Folio ADD NoPostFlag BIT NULL, HotelID NVARCHAR(50) NULL;
ALTER TABLE dbo.TransactionCode ADD TransactionGroup INT NULL, CurrencyCode NVARCHAR(10) NULL, HotelID NVARCHAR(50) NULL;
GO
-- Rooms and the numbering counters, for op_sweep's rollback proof (tests/sql_live.rs): the columns the room and
-- walk-in procedures (srCI_HousekeepingRooms, srCI_HousekeepingUpdateRoomStatus, srCI_AssignRoomToFolio,
-- srCI_WalkInCreateReservation) touch, with seeded rows the sweep's writes hit.
CREATE TABLE dbo.Room (
    RoomCode VARCHAR(20) NOT NULL PRIMARY KEY, RoomTypeCode VARCHAR(10), HskpStation VARCHAR(10), HSKPOccupied BIT,
    HSKPClean BIT, Inspected BIT, SYSOccupied BIT, RStatus INT);
CREATE TABLE dbo.HSKPStatusLog (
    SeqNo INT IDENTITY(1,1) PRIMARY KEY, RoomCode VARCHAR(20), ClerkID NVARCHAR(100), ChangeTime DATETIME,
    OldClean BIT, OldIns BIT, NewClean BIT, NewIns BIT);
CREATE TABLE dbo.AutoFolioNumber (FolioNumber DECIMAL(18,0), FolioSubNumber DECIMAL(5,0));
CREATE TABLE dbo.AutoConfNumber (ConfNumber DECIMAL(18,0));
CREATE TABLE dbo.FolioRate (
    FolioNum DECIMAL(18,0), hDate DATETIME, RateAmount DECIMAL(18,2), ToDate DATETIME, isCancel BIT, RateOverride BIT);
